import{_ as r,C as i,o as a,c as o,E as s,a0 as n}from"./chunks/framework.CV8GZ7IB.js";const f=JSON.parse('{"title":"Microsphere Projects — a layered enhancement system for Java and Spring","description":"The official site of Microsphere Projects — 32 sub-projects across five architectural layers, with unified BOMs and a full compatibility matrix.","frontmatter":{"layout":"page","title":"Microsphere Projects — a layered enhancement system for Java and Spring","description":"The official site of Microsphere Projects — 32 sub-projects across five architectural layers, with unified BOMs and a full compatibility matrix.","outline":false},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),d={name:"index.md"};function c(l,e,p,h,u,g){const t=i("HomeHero");return a(),o("div",null,[s(t),e[0]||(e[0]=n('<hr><h2 id="microsphere-in-one-minute" tabindex="-1">Microsphere in one minute <a class="header-anchor" href="#microsphere-in-one-minute" aria-label="Permalink to &quot;Microsphere in one minute&quot;">​</a></h2><p>Microsphere Projects is an open-source organisation of <strong>36 GitHub repositories</strong> that provides layered enhancements for the Java and Spring ecosystem. It is not a single framework but a <strong>composable capability matrix</strong>: you can use <code>microsphere-java</code> purely as a utility library, add Spring Cloud extensions to get restart-free Feign refresh, or stack observability, internationalisation and multi-active routing on top.</p><p>Every project shares the same engineering contract:</p><ul><li><strong>One Group ID</strong> — <code>io.github.microsphere-projects</code></li><li><strong>One BOM convention</strong> — every sub-project ships a <code>*-dependencies</code> module, so importing once aligns all versions</li><li><strong>One build baseline</strong> — the <code>microsphere-build</code> parent POM covers Java 8 / 11 / 17 / 21 / 25</li><li><strong>Two release lines</strong> — <code>main</code> targets the current generation (Spring Boot 3/4, Spring Cloud 2022–2025), while <code>1.x</code> serves existing systems (Spring Boot 2, Hoxton–2021)</li></ul><h2 id="where-it-fits" tabindex="-1">Where it fits <a class="header-anchor" href="#where-it-fits" aria-label="Permalink to &quot;Where it fits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If you need to…</th><th>Capability</th><th>Entry point</th></tr></thead><tbody><tr><td>Cut slow startup caused by serial bean creation</td><td>Resolve the dependency graph and build independent singletons concurrently</td><td><a href="/projects/microsphere-spring">Spring</a></td></tr><tr><td>Stop redeploying for every configuration change</td><td>Hot-refresh Feign, property sources and i18n messages on change</td><td><a href="/projects/microsphere-spring-cloud">Spring Cloud</a></td></tr><tr><td>See where slow SQL goes in production</td><td>Intercept SQL non-intrusively and feed Micrometer</td><td><a href="/projects/microsphere-observability">Observability</a></td></tr><tr><td>Add rate limiting and circuit breaking</td><td>One model across web, database and Redis</td><td><a href="/projects/microsphere-alibaba-sentinel">Sentinel</a></td></tr><tr><td>Centralise messages for many locales</td><td>Layered message sources plus a centralised i18n server</td><td><a href="/projects/microsphere-i18n">i18n</a></td></tr><tr><td>Register one instance with several registries</td><td>Unified multi-registry API and a union discovery client</td><td><a href="/projects/microsphere-spring-cloud">Spring Cloud</a></td></tr><tr><td>Prefer same-zone calls in an active-active setup</td><td>Zone-aware routing with cross-zone fallback</td><td><a href="/projects/microsphere-multiactive">Multiactive</a></td></tr><tr><td>Avoid duplicating gateway routes per service</td><td>The <code>we://</code> scheme routes discovered endpoints dynamically</td><td><a href="/projects/microsphere-gateway">Gateway</a></td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/architecture">Architecture</a> — the five layers and how every sub-project fits together, fully interactive</li><li><a href="/projects/">All projects</a> — the complete catalogue with search, layer filters and sorting</li><li><a href="/guide/getting-started">Getting started</a> — from importing a BOM to your first feature</li></ul>',9))])}const y=r(d,[["render",c]]);export{f as __pageData,y as default};
